  procedure run_all(p_persona in varchar2) is
    l_n      number;
    l_fail   varchar2(32767);
    l_denied pls_integer := 0;
  begin
    load;
    for i in 1 .. g_q.count loop
      begin
        execute immediate 'select count(*) from (' || g_q(i) || ')' into l_n;
      exception
        when others then
          if sqlcode = -20403 then
            l_denied := l_denied + 1;
          else
            l_fail := substr(l_fail || chr(10) || g_l(i) || ': ' || substr(sqlerrm, 1, 200), 1, 30000);
          end if;
      end;
    end loop;
    dbms_output.put_line(p_persona || ': ' || g_q.count || ' queries, ' || l_denied || ' correctly denied');
    ut.expect(l_fail, p_persona || ' failures').to_be_null();
  end run_all;

  procedure anonymous is
  begin
    oan_ctx_pkg.set_test_viewer(null, 'NONE');
    run_all('anonymous');
  end anonymous;

  procedure member is
  begin
    oan_ctx_pkg.set_test_viewer(uid('tester.chen'), 'MEMBER');
    run_all('member');
  end member;

  procedure admin is
  begin
    oan_ctx_pkg.set_test_viewer(uid('tester.bala'), 'MEMBER', 'Y', 'ADMIN:PRIVACY_OFFICER');
    run_all('admin');
  end admin;

  procedure staff is
  begin
    oan_ctx_pkg.set_test_viewer(uid('tester.asha'), 'MEMBER', 'N', 'MODERATOR:SUPPORT:CONTENT_EDITOR:EVENT_MANAGER:CHAPTER_ADMIN');
    run_all('staff');
